begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000021');
insert into public.lesson_drafts(id,created_by,title,language,target_filename,korean_filename,target_source,korean_source,parsed_entries,validation_status,phrase_count,chapter_count,section_count)
values ('20000000-0000-4000-8000-000000000021','00000000-0000-4000-8000-000000000021','Takeover','english','en.txt','ko.txt','One','하나','[{"kind":"phrase"}]','validated',1,0,0);
update public.lesson_drafts set publication_status='published',published_at='2026-09-08T00:00:00Z',audio_manifest='[{}]' where id='20000000-0000-4000-8000-000000000021';
set local role service_role;
select public.get_learner_preferences('00000000-0000-4000-8000-000000000021','UTC');
select set_config('test.start',public.learner_practice('00000000-0000-4000-8000-000000000021','{"action":"start","instance":"21000000-0000-4000-8000-000000000001","operation":"21000000-0000-4000-8000-000000000002","lessonId":"20000000-0000-4000-8000-000000000021","lessonVersion":"2026-09-08T00:00:00Z","level":1,"stage":1,"settings":{"mode":"manual","speed":1}}')::text,true);
select set_config('test.old',jsonb_build_object('action','checkpoint','instance','21000000-0000-4000-8000-000000000001','operation','21000000-0000-4000-8000-000000000003','runId',current_setting('test.start')::jsonb->'record'->>'runId','generation',1,'revision',0,'kind','studied','nextUnit',0,'activeMs',1500)::text,true);
select public.learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.old')::jsonb);
select set_config('test.takeover',((current_setting('test.old')::jsonb - 'revision' - 'kind' - 'nextUnit' - 'activeMs') || '{"action":"takeover","instance":"21000000-0000-4000-8000-000000000004","operation":"21000000-0000-4000-8000-000000000005"}'::jsonb)::text,true);
select set_config('test.new',public.takeover_learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.takeover')::jsonb)::text,true);
select is(current_setting('test.new')::jsonb->>'generation','2','explicit takeover advances the generation');
select is(current_setting('test.new')::jsonb->>'revision','1','takeover preserves the latest revision');
select is(current_setting('test.new')::jsonb->'record'->>'activeMs','1500','takeover resumes the server-confirmed checkpoint');
select is(public.takeover_learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.takeover')::jsonb),current_setting('test.new')::jsonb,'a lost takeover response retries once');
select throws_ok($$select public.takeover_learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.takeover')::jsonb || '{"operation":"21000000-0000-4000-8000-000000000006","instance":"21000000-0000-4000-8000-000000000007"}')$$,'P0001','ownership-lost','a competing confirmation cannot steal the new generation');
select throws_ok($$select public.learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.old')::jsonb)$$,'P0001','ownership-lost','even an already committed old receipt is rejected');
select throws_ok($$select public.learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.old')::jsonb || '{"action":"renew"}')$$,'P0001','ownership-lost','old renewal is rejected');
select throws_ok($$select public.learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.old')::jsonb || '{"operation":"21000000-0000-4000-8000-000000000008","kind":"advance","nextUnit":1,"confirmedCycles":3,"revision":1}')$$,'P0001','ownership-lost','old completion is rejected');
select is(public.read_learner_journal('00000000-0000-4000-8000-000000000021')->'activeLease'->>'generation','2','read-only journal exposes a confirmation fence, not the instance secret');
select ok(not (public.read_learner_journal('00000000-0000-4000-8000-000000000021')->'activeLease' ? 'instance'),'instance remains private');
reset role;
select ok(not has_function_privilege('anon','public.takeover_learner_practice(uuid,jsonb)','execute'),'anonymous callers cannot take over directly');
select ok(not has_function_privilege('authenticated','public.takeover_learner_practice(uuid,jsonb)','execute'),'authenticated callers cannot bypass the API');
update public.learner_practice_accounts set lease_until=null,instance=null where user_id='00000000-0000-4000-8000-000000000021';
select throws_ok($$select public.takeover_learner_practice('00000000-0000-4000-8000-000000000021',current_setting('test.takeover')::jsonb)$$,'P0001','ownership-lost','release fences an old takeover receipt');
select * from finish();
rollback;
